-- Dữ liệu DEMO cho Lịch trực Bảo Vệ Việt Hưng.
-- Chạy SAU supabase.sql, chỉ khi chưa thiết lập tài khoản trưởng ban. Có thể chạy lại, sẽ ghi đè bản demo.
--   Trưởng ban: mã số VH01, PIN 543
--   11 nhân viên: mã số VH02 … VH12, PIN 123
-- Đây chỉ là PIN demo, rất yếu. Trước khi dùng thật hãy đổi PIN (Nhân sự → Sửa) hoặc xóa dữ liệu demo.
-- Hồ sơ trong tệp là dữ liệu giả (tên, số điện thoại), hãy thay bằng thông tin thật.

insert into public.accounts (staff_id, code, pin_hash, is_head) values ('sd01', 'VH01', extensions.crypt('543', extensions.gen_salt('bf')), true)
  on conflict (staff_id) do update set code = excluded.code, pin_hash = excluded.pin_hash, is_head = excluded.is_head, failed = 0, locked_until = null;
