-- PIN demo rất yếu: lần đăng nhập đầu mọi tài khoản demo phải tự đổi sang PIN riêng (ít nhất 6 ký tự).
alter table public.accounts add column if not exists must_change boolean not null default false;
update public.accounts set must_change = true where staff_id like 'sd%';
